hold_ticks := 0
if ((#Plug).plug_power < 5) {
hold_ticks = hold_ticks + 1
    if (hold_ticks >= 600) {
(#Speaker).speaker_speak("Device is idle")
        break
}
}
else {
hold_ticks = 0
}
n := 0
if (n >= 3) {
break
}
(#Speaker).speaker_speak("Device is idle")
n = n + 1

